# Hypothesis: Convert 3->7 in sparse rows, leave dense rows unchanged
output_grid3 = []
for i, row in enumerate(input_grid):
    if is_separator_row(row):
        # Dense row: keep as-is
        output_grid3.append(row)
    else:
        # Sparse row: convert 3->7
        output_grid3.append([7 if x == 3 else x for x in row])

# Print the output
for i, row in enumerate(output_grid3):
    print(f"Row {i}: {' '.join(map(str, row))}")

